  const voteStatusDescription = hasVotedThisEpoch === void 0 ? "Unable to confirm the latest vote activity. Resetting will remove all vote allocations once processed." : isCurrentEpochVote ? "This lock has active votes in the current epoch. Resetting will remove all vote allocations." : "This lock has votes carried over from a previous epoch. Resetting will remove all vote allocations.";
